    calc: function(v){var r=v.rate/100/12;var n=v.years*12;var fv=v.principal*Math.pow(1+r,n)+v.monthly*((Math.pow(1+r,n)-1)/r);var contributed=v.principal+v.monthly*n;return{result:'$'+fv.toLocaleString(undefined,{maximumFractionDigits:0}),chart:Charts.bar([contributed,fv],['Contributed','Future Value']),extra:'Interest earned: $'+(fv-contributed).toLocaleString(undefined,{maximumFractionDigits:0})};},
